// Legacy Handler
PROCEDURE Process_Journal(
  p_id IN NUMBER,
  p_amount IN NUMBER
) IS
BEGIN
  SELECT balance INTO v_bal FROM accounts WHERE id = p_id FOR UPDATE;
  IF v_bal >= p_amount THEN
    UPDATE accounts SET balance = balance - p_amount WHERE id = p_id;
    COMMIT;
  END IF;
END;

