// Modern Resilient Microservice
export async function processJournal(ctx: Context, tx: TxPayload) {
  const txn = await db.beginTransaction({ isolation: 'SERIALIZABLE' });
  const ledger = await txn.ledger.verifyAndDebit(tx.id, tx.amount);
  await eventBus.publish('tx.committed', { txId: ledger.id, latency: ctx.elapsed });
  return { success: true, ref: ledger.hash };
}

// Modern REST Endpoint
export async function getOrganization(orgId: string) {
  const org = await db.organizations.findUnique({ where: { id: orgId } });
  return { organization: org, provisioned: true };
}

